package com.reed.fcmguard;

import android.content.Context;

/**
 * The colour palettes the user can pick. Each is a theme overlay ({@code Palette.*},
 * generated by tools/gen_palettes.py with light and night variants) that redefines the
 * {@code pal_*} colour attributes; Classic leaves the AppTheme defaults in place.
 */
final class Palettes {
    static final String DEFAULT = "classic";

    static final String[] IDS = {
            "classic", "hyper_blue", "guardian_teal", "indigo_dusk", "google",
            "sakura", "sunset_amber", "graphite", "aurora"
    };

    static final int[] STYLES = {
            R.style.Palette_Classic, R.style.Palette_HyperBlue, R.style.Palette_GuardianTeal,
            R.style.Palette_IndigoDusk, R.style.Palette_Google, R.style.Palette_Sakura,
            R.style.Palette_SunsetAmber, R.style.Palette_Graphite, R.style.Palette_Aurora
    };

    static final int[] NAMES = {
            R.string.palette_classic, R.string.palette_hyper_blue, R.string.palette_guardian_teal,
            R.string.palette_indigo_dusk, R.string.palette_google, R.string.palette_sakura,
            R.string.palette_sunset_amber, R.string.palette_graphite, R.string.palette_aurora
    };

    private Palettes() {}

    static int indexOf(String id) {
        for (int i = 0; i < IDS.length; i++) {
            if (IDS[i].equals(id)) return i;
        }
        return 0;
    }

    static int current(Context context) {
        return indexOf(ThemeHelper.getPalette(context));
    }
}
